INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10901, '2 Chronicles 23:6', '2 Chronicles', 23, 6, '&nbsp;ياد ساتئ چې صرف اِمامان او ليويان به د مالِک خُدائ کور ته ننوځى د چا چې د خِدمت نمبر وى. هغوئ ځکه ننوتلے شى چې هغوئ پاک کړے شوى دى، خو باقى نور خلق به خامخا د مالِک خُدائ اصُول منى او بهر دې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10902, '2 Chronicles 23:7', '2 Chronicles', 23, 7, '&nbsp;ليويان به د بادشاه نه ګېرچاپېره د حِفاظت دپاره ولاړ وى، چې خپلې تُورې يې راويستلې وى او چې بادشاه چرته هم ځى نو هلته به ورسره ځى. نور هر څوک چې د مالِک خُدائ کور ته د ننوتلو کوشش وکړى نو هغه دې ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10903, '2 Chronicles 23:8', '2 Chronicles', 23, 8, '&nbsp;ليويانو او د يهوداه خلقو د يهويدع په اصُولو باندې عمل وکړو. کوم څوکيداران چې د سبت په ورځ د کار نه چُهټى کېدل، نو هغوئ ته دا اجازت نۀ وو چې کور ته لاړ شى نو داسې د هر فوجى مشر سره خپل څوکيداران موجود وُو يعنې هغه څوکيداران چې د کار نه يې چهټى کوله او هغه کسان چې کار له راتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10904, '2 Chronicles 23:9', '2 Chronicles', 23, 9, '&nbsp;يهويدع آفسرانو له هغه نېزې او ډالونه ورکړل کوم چې د داؤد بادشاه وُو او چې د مالِک خُدائ په کور کښې ساتلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10905, '2 Chronicles 23:10', '2 Chronicles', 23, 10, '&nbsp;هغۀ د مالِک خُدائ د کور په مخکښې ګېرچاپېره سړى مقرر کړل چې تُورې يې د دې دپاره راويستلې وې چې د بادشاه حِفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10906, '2 Chronicles 23:11', '2 Chronicles', 23, 11, '&nbsp;بيا يهويدع يوآس بهر بوتلو، تاج يې د هغۀ په سر کېښودو او هغۀ له يې د احکامو کِتاب ورکړو. نو هغه بادشاه شو. يهويدع اِمام او د هغۀ زامنو د مقررولو د نښې په طور د يوآس سر په تېلو غوړ کړو او ټولو چغه ووهله، ”بادشاه زنده‌باد!“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10907, '2 Chronicles 23:12', '2 Chronicles', 23, 12, '&nbsp;عتلياه د بادشاه دپاره د خوشحالۍ چغې واورېدلې، نو هغه د مالِک خُدائ کور ته تېزه لاړه، چرته چې خلق راغونډ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10908, '2 Chronicles 23:13', '2 Chronicles', 23, 13, '&nbsp;هغې هلته د مالِک خُدائ د کور د دروازې په خولۀ کښې نوے بادشاه وليدو، چې د هغه ستنو سره ولاړ وو چې د بادشاهانو دپاره مخصوصې وې او ګېرچاپېره ترې نه فوجى آفسران او د بيګلو غږوونکى تاو وُو. ټولو خلقو د خوشحالۍ نه چغې وهلې او بيګلې يې غږولې، او د مالِک خُدائ د کور موسيقارانو د موسيقۍ د څيزونو سره دا جشن روان کړے وو. هغې د خفګان نه خپلې جامې وشلولې او چغه يې ووهله، ”غدار! غدار!“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10909, '2 Chronicles 23:14', '2 Chronicles', 23, 14, '&nbsp;يهويدع دا نۀ غوښتل چې عتلياه دې د مالِک خُدائ په کور کښې ووژلے شى، نو هغۀ خپل فوجى آفسران راوغوښتل او ورته يې ووئيل، ”هغه د څوکيدارانو د قطارونو په مينځ کښې وباسئ او هر څوک چې د هغې د بچ کولو کوشش کوى نو هغه ووژنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10910, '2 Chronicles 23:15', '2 Chronicles', 23, 15, '&nbsp;هغوئ هغه ونيوله، محل ته يې بوتله او هلته يې د آسونو د دروازې سره ووژله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10911, '2 Chronicles 23:16', '2 Chronicles', 23, 16, '&nbsp;يهويدع اِمام يوآس بادشاه او خلق د ځان سره کړل چې د هغۀ سره يو لوظ وکړى چې هغوئ به د مالِک خُدائ وفادار اوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10912, '2 Chronicles 23:17', '2 Chronicles', 23, 17, '&nbsp;بيا هغوئ ټول د بعل عبادتخانې ته لاړل او هغه يې راوغورزوله. هغوئ هلته قربان‌ګاه او بُتان ټوټې کړل او متان د بعل اِمام يې د قربان‌ګاه په مخکښې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10913, '2 Chronicles 23:18', '2 Chronicles', 23, 18, '&nbsp;يهويدع اِمامان او ليويان د مالِک خُدائ د کور د کار مشران مقرر کړل. د هغوئ کار هغه ذمه وارۍ سر ته رسَول وُو چې کومې ورته داؤد بادشاه حواله کړې وې او چې د موسىٰ د قانون په مطابق هغه نذرانې وسوزوى چې کومې مالِک خُدائ ته د موسيقۍ او خوشحالۍ سره پېش کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10914, '2 Chronicles 23:19', '2 Chronicles', 23, 19, '&nbsp;يهويدع د مالِک خُدائ د کور په دروازو باندې د دې دپاره هم څوکيداران مقرر کړل چې څوک ناپاک وى نو هغه بهر ايسار کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10915, '2 Chronicles 23:20', '2 Chronicles', 23, 20, '&nbsp;فوجى آفسران، مشران خلق، آفسران او نور پاتې ټول خلق د يهويدع سره په هغه عمل کښې ملګرى وُو چې کله بادشاه د مالِک خُدائ کور نه محل ته راوستلے شو. هغوئ په پاسنۍ دروازه راننوتل او بادشاه په خپل تخت کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10916, '2 Chronicles 23:21', '2 Chronicles', 23, 21, '&nbsp;ټول خلق خوشحاله وُو او اوس د عتلياه د وژلو په وجه په ښار کښې خاموشى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10917, '2 Chronicles 24:1', '2 Chronicles', 24, 1, '&nbsp;يوآس د اوو کالو په عُمر کښې د يهوداه بادشاه شو او څلوېښت کاله يې په يروشلم باندې بادشاهى وکړه. د هغۀ مور د بيرسبع د ښار ضِبياه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10918, '2 Chronicles 24:2', '2 Chronicles', 24, 2, '&nbsp;ترڅو پورې چې يهويدع اِمام ژوندے وو نو يوآس هم هغه کار کولو چې مالِک خُدائ ورباندې خوشحالېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10919, '2 Chronicles 24:3', '2 Chronicles', 24, 3, '&nbsp;يهويدع د يوآس بادشاه دپاره دوه ښځې خوښې کړې او د هغۀ زامن او لوڼه پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10920, '2 Chronicles 24:4', '2 Chronicles', 24, 4, '&nbsp;کله چې يوآس بادشاه وو نو هغۀ دا فېصله وکړه چې د مالِک خُدائ د کور مرمت دې وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10921, '2 Chronicles 24:5', '2 Chronicles', 24, 5, '&nbsp;هغۀ اِمامانو او ليويانو له حُکم ورکړو چې د يهوداه ښارونو ته لاړ شى او د ټولو خلقو نه دومره پېسې راغونډې کړى چې د مالِک خُدائ په کور کښې کلنے مرمت ورباندې وکړى. هغۀ ورته ووئيل چې دا کار سمدستى وکړئ، خو ليويانو دا کار سمدستى ونۀ کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10922, '2 Chronicles 24:6', '2 Chronicles', 24, 6, '&nbsp;نو هغۀ د هغوئ مشر يهويدع راوغوښتلو او تپوس يې ترې نه وکړو، ”تاسو دې ته پام ولې نۀ کولو چې ليويانو د يهوداه او يروشلم نه هغه محصُول راغونډولو کوم چې د مالِک خُدائ خِدمت کوونکى موسىٰ د خلقو نه دا غوښتل چې دا محصُول د مالِک خُدائ د حضور د خېمې دپاره ورکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10923, '2 Chronicles 24:7', '2 Chronicles', 24, 7, '&nbsp;د عتلياه يعنې د هغه بدکارې ښځې منونکو د مالِک خُدائ د کور نه د ډېر وخت نه غلا کوله او ټول مقدس څيزونه يې هم د بعل په عبادت کښې استعمالول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10924, '2 Chronicles 24:8', '2 Chronicles', 24, 8, '&nbsp;بادشاه ليويانو له حُکم ورکړو چې د چندې دپاره يو صندوق جوړ کړى او د مالِک خُدائ د کور په دروازه کښې يې کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10925, '2 Chronicles 24:9', '2 Chronicles', 24, 9, '&nbsp;هغۀ په ټول يروشلم او يهوداه کښې هر يو کس له دا خبر ورولېږلو چې مالِک خُدائ له هغه محصُول راوړى کوم چې په وړومبى ځل د خُدائ پاک خِدمت کوونکى موسىٰ په صحرا کښې راغونډ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10926, '2 Chronicles 24:10', '2 Chronicles', 24, 10, '&nbsp;په دې باندې خلق او د هغوئ مشران خوشحاله شول او خپلې د محصُول پېسې يې راوړې او صندوق يې ډک کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10927, '2 Chronicles 24:11', '2 Chronicles', 24, 11, '&nbsp;ليويانو به هره ورځ هغه صندوق شاهى آفسر له وړلو کوم آفسر چې د دې ذمه وار وو. کله به هم چې دا ډک وو، نو شاهى منشى او د مشر اِمام کس به پېسې راويستلې او صندوق به يې واپس خپل ځائ ته وړلو. نو داسې هغوئ ډېرې پسې راغونډې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10928, '2 Chronicles 24:12', '2 Chronicles', 24, 12, '&nbsp;بادشاه او يهويدع به پېسې هغه چا له ورکولې کوم چې د مالِک خُدائ د کور د مرمت کولو مشران وُو او هغوئ د کاڼو ګِلکاران، ترکاڼان او لوهاران د مرمت دپاره په مزدورۍ ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10929, '2 Chronicles 24:13', '2 Chronicles', 24, 13, '&nbsp;هغوئ ټولو سخت محنت کولو او د مالِک خُدائ کور يې خپل اصلى حالت ته بيا راوستلو، هم هغه شان مضبوط لکه څنګه چې مخکښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10930, '2 Chronicles 24:14', '2 Chronicles', 24, 14, '&nbsp;کله چې مرمت ختم شو، نو هغه پاتې شوى سرۀ زر او سپين زر بادشاه او يهويدع له ورکړے شول، چې هغوئ دا د مالِک خُدائ د کور د جامونو او نور سامان جوړولو دپاره استعمال کړل. د يوآس د مالِک خُدائ نه اوړېدل چې ترڅو پورې يهويدع ژوندے وو، نو نذرانې به مسلسل د مالِک خُدائ په کور کښې پېش کېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10931, '2 Chronicles 24:15', '2 Chronicles', 24, 15, '&nbsp;کله چې يهويدع د يو سل او دېرشو کالو ښۀ پوخ عُمر ته ورسېدو، نو هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10932, '2 Chronicles 24:16', '2 Chronicles', 24, 16, '&nbsp;هغه د داؤد په شاهى اديره کښې ښخ شو ځکه چې هغۀ په اِسرائيل کښې د خُدائ پاک او د هغۀ د کور ډېر خِدمت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10933, '2 Chronicles 24:17', '2 Chronicles', 24, 17, '&nbsp;خو چې کله يهويدع مړ شو، نو د يهوداه مشرانو يوآس بادشاه دې ته جوړ کړو چې هغوئ ته غوږ ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10934, '2 Chronicles 24:18', '2 Chronicles', 24, 18, '&nbsp;نو خلقو د مالِک خُدائ په کور کښې د هغۀ عبادت پرېښودو، دا هغه ځائ وو چرته چې د هغوئ پلار نيکۀ عبادت کولو او د دې په ځائ يې د بُتانو او د اشيرې بُت د نښو عبادت شروع کړو. د دې ګناهونو د جرم په وجه هغوئ په يهوداه او يروشلم باندې د مالِک خُدائ غصه راوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10935, '2 Chronicles 24:19', '2 Chronicles', 24, 19, '&nbsp;مالِک خُدائ هغوئ له پېغمبران ورولېږل چې خلق هغه واپس راوګرځوى، پېغمبرانو به هغوئ له خبردارے ورکولو خو خلقو ورته غوږ ونۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10936, '2 Chronicles 24:20', '2 Chronicles', 24, 20, '&nbsp;بيا د خُدائ پاک روح د يهويدع اِمام په زوئ زکرياه باندې راغلو. هغه په يو اوچت ځائ باندې ودرېدو او آواز يې وکړو، ”مالِک خُدائ، خُدائ پاک دا تپوس کوى چې تاسو د هغۀ د حُکمونو نافرمانى ولې کوئ او په خپل ځان باندې تباهى ولې راولئ. تاسو هغه پرېښودو، نو په دې وجه هغۀ تاسو هم پرېښودئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10937, '2 Chronicles 24:21', '2 Chronicles', 24, 21, '&nbsp;يوآس بادشاه د زکرياه خِلاف په يو سازش کښې ملګرتيا وکړه او د بادشاه په حُکم يې د مالِک خُدائ د کور په دربار کښې زکرياه سنګسار کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10938, '2 Chronicles 24:22', '2 Chronicles', 24, 22, '&nbsp;بادشاه هغه د وفادارۍ خِدمت هېر کړو چې د زکرياه پلار يهويدع د هغۀ دپاره کړے وو او هغۀ زکرياه ووژلو. کله چې زکرياه مړ کېدو، نو هغۀ چغه ووهله، ”مالِک خُدائ دې زما په حال نظر وکړى او زما بدل دې تا نه واخلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10939, '2 Chronicles 24:23', '2 Chronicles', 24, 23, '&nbsp;کله چې په هغه کال خزان راغلو، نو د شام لښکر په يهوداه او يروشلم باندې حمله وکړه او ټول مشران يې ووژل او ټول مال غنيمت يې د دمشق بادشاه له يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10940, '2 Chronicles 24:24', '2 Chronicles', 24, 24, '&nbsp;اګر چې شامى لښکر وړوکے وو، خو مالِک خُدائ د هغوئ مدد وکړو چې د يهوداه دومره لوئ لښکر له شکست ورکړى ځکه چې د يهوداه خلقو مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک پرېښے وو. نو داسې يوآس بادشاه ته سزا مِلاو شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10941, '2 Chronicles 24:25', '2 Chronicles', 24, 25, '&nbsp;کله چې شامى لښکر واپس لاړو نو يوآس سخت زخمى پاتې وو، نو وروستو بيا د هغۀ دوو آفسرانو د هغۀ خِلاف منصوبه جوړه کړه او هغه يې په خپل کټ کښې ووژلو د دې دپاره چې د يهويدع اِمام د زوئ د قتل بدله ترې نه واخلى. هغه د داؤد په ښار کښې ښخ شو، خو په شاهى اديره کښې ښخ نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10942, '2 Chronicles 24:26', '2 Chronicles', 24, 26, '&nbsp;د هغۀ خِلاف چې چا منصوبه جوړه کړې وه هغه يو زاباد وو، چې هغه د يوې عمونى ښځې زوئ وو چې د هغې نوم سماعت وو، او بل يهوزبد وو چې دے د يوې موآبۍ ښځې زوئ وو چې د هغې نوم سِمريت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10943, '2 Chronicles 24:27', '2 Chronicles', 24, 27, '&nbsp;د بادشاهانو د کِتاب په تفسير کښې د يوآس د زامنو قيصې، هغه پېغامونه چې د هغۀ خِلاف شوى دى، او د مالِک خُدائ د کور د بيا جوړولو په حقله قيصه شامله ده. د هغۀ زوئ امصياه د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10944, '2 Chronicles 25:1', '2 Chronicles', 25, 1, '&nbsp;امصياه د پينځويشتو کالو په عُمر کښې بادشاه شو او يو کم دېرش کاله يې په يروشلم باندې حکومت وکړو. د هغۀ مور د يروشلم يهوعدان وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10945, '2 Chronicles 25:2', '2 Chronicles', 25, 2, '&nbsp;هغۀ هغه هر کار کولو چې په څۀ باندې مالِک خُدائ رضا کېدو خو د زړۀ د اخلاصه يې نۀ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10946, '2 Chronicles 25:3', '2 Chronicles', 25, 3, '&nbsp;کله چې د هغۀ بادشاهى مضبوطه شوه، نو هغۀ هغه آفسران ووژل چا چې د هغۀ پلار وژلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10947, '2 Chronicles 25:4', '2 Chronicles', 25, 4, '&nbsp;خو هغۀ د هغوئ بچى ونۀ وژل او په هغه څۀ يې عمل وکړو چې مالِک خُدائ د موسىٰ په شريعت کښې د هغې حُکم کړے وو، ”مور پلار دې د هغه جرمونو په وجه نۀ شى وژلے کوم چې د هغوئ بچو کړى وى او بچى دې د هغه جرمونو په وجه نۀ شى وژلے کوم چې د هغوئ مور پلار کړى وى، يو کس دې صِرف د هغه جرم په وجه وژلے شى چې هغۀ په خپله کړے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10948, '2 Chronicles 25:5', '2 Chronicles', 25, 5, '&nbsp;امصياه بادشاه د يهوداه او د بنيامين د قبيلو ټول سړى د خپلو خپلو کورَنو په مطابق په فوجى ډلو کښې رايوځائ کړل او د زرو کسانو د ډلو او د سلو کسانو د ډلو دپاره يې فوجى مشران مقرر کړل. په دې کښې هغه ټول سړى شامل وُو چې عُمر يې شل کاله يا د دې نه زيات وو، چې ټول درې لاکه وُو. هغوئ خوښ کړے شوى فوجيان وُو، د جنګ دپاره تيار وُو او د نېزو او ډالونو په استعمالولو کښې تکړه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10949, '2 Chronicles 25:6', '2 Chronicles', 25, 6, '&nbsp;د دې نه علاوه، هغۀ د اِسرائيل نه سل زره فوجيان تقريباً د درې زره او څلور سوه کلو د سپينو زرو په قيمت باندې په مزدورۍ ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10950, '2 Chronicles 25:7', '2 Chronicles', 25, 7, '&nbsp;خو يو پېغمبر بادشاه له ورَغلو او ورته يې ووئيل، ”د اِسرائيل دا فوجيان ځان سره مۀ بوځه. مالِک خُدائ د اِفرائيم د قبيلې د دې فوجيانو مل نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10951, '2 Chronicles 25:8', '2 Chronicles', 25, 8, '&nbsp;کېدے شى ستا خيال دا وى چې د هغوئ په وجه به تاسو په جنګ کښې تکړه شئ، خو دا د خُدائ پاک کار دے چې هغه دا طاقت لرى چې چا له فتح يا شکست ورکړى. خُدائ پاک به ستاسو د دشمنانو په وجه تاسو له شکست درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10952, '2 Chronicles 25:9', '2 Chronicles', 25, 9, '&nbsp;امصياه د پېغمبر نه تپوس وکړو، ”خو د هغه ټولو سپينو زرو به څۀ کيږى چې ما په مزدورۍ کښې ورکړى دى؟“ هغه پېغمبر ورته وفرمائيل، ”مالِک خُدائ تا له د هغې نه زيات درکولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10953, '2 Chronicles 25:10', '2 Chronicles', 25, 10, '&nbsp;نو امصياه هغه د مزدورۍ فوجيان واپس ولېږل او ورته يې ووئيل چې کورونو ته لاړ شئ. نو هغوئ کورونو ته لاړل او د يهوداه خلقو ته سخت غصه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10954, '2 Chronicles 25:11', '2 Chronicles', 25, 11, '&nbsp;امصياه خپل ځان بيا تکړه کړو او د مالګې مېدان ته يې خپل لښکر روان کړو. هغوئ هلته جنګ وکړو او لس زره ادومى فوجيان يې ووژل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10955, '2 Chronicles 25:12', '2 Chronicles', 25, 12, '&nbsp;او نور لس زره يې ونيول. هغوئ قېديان د سِلح په ښار کښې د کمر سر ته وخېژول او راوې غورزول، نو داسې هغوئ لاندې په ګټو کښې مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10956, '2 Chronicles 25:13', '2 Chronicles', 25, 13, '&nbsp;په دې دوران کښې د مزدورۍ کوم فوجيان چې امصياه کورونو ته لېږلى وُو نو هغوئ د سامريه او بيت‌حورون په مينځ کښې د يهوداه په يو څو ښارونو حمله وکړه. هغوئ درې زره کسان ووژل او ډېر مال غنيمت يې يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10957, '2 Chronicles 25:14', '2 Chronicles', 25, 14, '&nbsp;کله چې امصياه ادوميانو له د شکست ورکولو نه پس راوګرځېدو، نو هغۀ د هغوئ بُتان د ځان سره راوړل، دا يې ودرول، د هغې عبادت يې وکړو او خوشبويۍ يې ورته وسوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10958, '2 Chronicles 25:15', '2 Chronicles', 25, 15, '&nbsp;په دې باندې مالِک خُدائ غصه شو، نو هغۀ امصياه له يو پېغمبر ورولېږلو. پېغمبر ورته وفرمائيل، ”تا د هغه پردو معبودانو عبادت ولې کړے دے چې هغوئ ستا د لاس نه خپل خلق هم نۀ شول بچ کولے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10959, '2 Chronicles 25:16', '2 Chronicles', 25, 16, '&nbsp;نو امصياه ورته ووئيل، ”د کله نه تۀ مونږ د بادشاه مشير مقرر کړے يې؟ خولۀ دې بنده کړه، ګنې ووبه دې وژنم.“ پېغمبر خبرې بندې کړې خو دا يې وفرمائيل، ”اوس ما ته پته ولګېده چې خُدائ پاک ستا د تباه کولو فېصله کړې ده دا ځکه چې تا دا هر څۀ وکړل او زما نصيحت ته دې پام نۀ دے کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10960, '2 Chronicles 25:17', '2 Chronicles', 25, 17, '&nbsp;د يهوداه بادشاه امصياه او د هغۀ مشيرانو د اِسرائيل د بادشاهۍ خِلاف منصوبه جوړه کړه. بيا هغۀ د اِسرائيل بادشاه يهوآس ته يو پېغام ولېږلو، څوک چې د يهوآخز زوئ او د ياهُو نمسے وو، چې جنګ له راوړاندې شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10961, '2 Chronicles 25:18', '2 Chronicles', 25, 18, '&nbsp;يهوآس امصياه له دا پېغام ولېږلو، ”يو ځل د لبنان په غرونو کښې د ازغو بوټى د دِيار ونې له دا پېغام ولېږلو، زما زوئ له ستا لور راکړه چې وادۀ يې کړى. نو بيا يو ځنګلى ځناور هلته تېرېدو او د ازغو په بوټى يې پښې کېښودې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10962, '2 Chronicles 25:19', '2 Chronicles', 25, 19, '&nbsp;نو امصياه، ادوميانو له دې اوس شکست ورکړے دے او مغروره شوے يې. خو زۀ تا له مشوره درکوم چې په خپل کور کښې کښېنه. داسې بلا ولې راپاروې چې هغه ستا او ستا په خلقو باندې صِرف تباهى راولى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10963, '2 Chronicles 25:20', '2 Chronicles', 25, 20, '&nbsp;خو امصياه ورته غوږ نۀ نيولو. خُدائ پاک غوښتل چې امصياه شکست وخورى، ځکه چې هغۀ د ادومى بُتانو عبادت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10964, '2 Chronicles 25:21', '2 Chronicles', 25, 21, '&nbsp;نو د اِسرائيل بادشاه يهوآس د يهوداه بادشاه امصياه خِلاف جنګ له لاړو. هغوئ په يهوداه کښې د بيت‌شمس سره يو بل ته مخامخ شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10965, '2 Chronicles 25:22', '2 Chronicles', 25, 22, '&nbsp;د يهوداه لښکر د اِسرائيل د لښکر نه شکست وخوړو او ټول فوجيان خپلو کورونو ته وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10966, '2 Chronicles 25:23', '2 Chronicles', 25, 23, '&nbsp;يهوآس امصياه ونيولو او يروشلم ته يې بوتلو. هلته هغۀ د اِفرائيم د دروازې نه واخله د ګوټ د دروازې پورې دېوال راوغورزولو، چې تقريباً دوه سوه او شل ګزه فاصله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10967, '2 Chronicles 25:24', '2 Chronicles', 25, 24, '&nbsp;هغۀ د مالِک خُدائ د کور ټول سرۀ زر او سپين زر د مالِ غنيمت په توګه سامريه ته يوړل، د مالِک خُدائ د کور هغه سامان چې د عوبيد ادوم اولاد د هغې حِفاظت کولو او د محل خزانې يې يوړې. هغۀ د ځان سره قېديان هم بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10968, '2 Chronicles 25:25', '2 Chronicles', 25, 25, '&nbsp;د يهوداه بادشاه امصياه د اِسرائيل د بادشاه يهوآس د مرګ نه پس پينځلس کاله ژوندے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10969, '2 Chronicles 25:26', '2 Chronicles', 25, 26, '&nbsp;امصياه چې نور هر څۀ هم کړى دى د هغۀ د بادشاهۍ د شروع نه واخله تر آخره پورې هغه د يهوداه او اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10970, '2 Chronicles 25:27', '2 Chronicles', 25, 27, '&nbsp;د هغه وخت نه واخله چې کله هغۀ د مالِک خُدائ خِلاف بغاوت وکړو، په يروشلم کښې دشمنانو د هغۀ خِلاف يوه منصوبه جوړوله. په آخر کښې هغه د لکيس ښار ته وتښتېدو، خو د هغۀ دشمنان په هغۀ پسې وُو او هلته يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10971, '2 Chronicles 25:28', '2 Chronicles', 25, 28, '&nbsp;د هغۀ لاش په يو آس باندې يروشلم ته راوړلے شو او هغه د داؤد ښار په شاهى اديره کښې ښخ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10972, '2 Chronicles 26:1', '2 Chronicles', 26, 1, '&nbsp;د يهوداه ټولو خلقو د امصياه شپاړس کلن زوئ عُزياه خوښ کړو چې د خپل پلار نه پس بادشاه جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10973, '2 Chronicles 26:2', '2 Chronicles', 26, 2, '&nbsp;دا د امصياه د مرګ نه پس وُو چې عُزياه ايلات بيا قبضه کړو او ښار يې دوباره جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10974, '2 Chronicles 26:3', '2 Chronicles', 26, 3, '&nbsp;عُزياه د شپاړسو کالو په عُمر کښې بادشاه شو او هغۀ په يروشلم باندې دوه پنځوس کاله بادشاهى وکړه. د هغۀ مور د يروشلم يکولياه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10975, '2 Chronicles 26:4', '2 Chronicles', 26, 4, '&nbsp;هغه د خپل پلار په نقش قدم باندې روان وو او هغه کار يې کولو چې مالِک خُدائ ورباندې خوشحالېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10976, '2 Chronicles 26:5', '2 Chronicles', 26, 5, '&nbsp;چې ترڅو پورې د هغۀ مذهبى مشير زکرياه ژوندے وو، نو هغۀ په وفادارۍ سره د مالِک خُدائ خِدمت کولو او خُدائ پاک هغۀ له برکت ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10977, '2 Chronicles 26:6', '2 Chronicles', 26, 6, '&nbsp;عُزياه د فلستيانو خِلاف جنګ له لاړو. هغۀ د جات، يبنه او اشدود ښارونو دېوالونه راوغورزول او د اشدود او باقى ټول فلستيه کښې يې د پَخو دېوالونو ښارونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10978, '2 Chronicles 26:7', '2 Chronicles', 26, 7, '&nbsp;خُدائ پاک فلستيانو له او هغه عربو له چې په جوربعل کښې اوسېدل او معونيانو له په شکست ورکولو کښې د هغۀ مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10979, '2 Chronicles 26:8', '2 Chronicles', 26, 8, '&nbsp;عمونيانو عُزياه له محصُول ورکولو او هغه دومره طاقتور شو چې د هغۀ شُهرت د مِصر پورې خور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10980, '2 Chronicles 26:9', '2 Chronicles', 26, 9, '&nbsp;عُزياه د يروشلم د پَخو دېوالونو مضبوطولو دپاره داسې وکړل چې د ګوټ د دروازې سره او د وادۍ د دروازې سره او هلته يې برجونه جوړ کړل چرته چې دېوال تاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10981, '2 Chronicles 26:10', '2 Chronicles', 26, 10, '&nbsp;هغۀ په بيابان کښې پاخۀ برجونه جوړ کړل او د اوبو ډېرې ډيګۍ يې وکنستلې، ځکه چې هغۀ د نمرپريواتۀ طرف ته د غرۀ په لمنو کښې او بيابان کښې د څاروو ډېرې رَمې لرلې. ځکه چې هغۀ د زميدارۍ سره مينه لرله، هغۀ خلقو ته وفرمائيل چې د غرونو په مُلک کښې د انګورو باغونه وکَرى او په آباده زمکه کښې پټى وکَرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10982, '2 Chronicles 26:11', '2 Chronicles', 26, 11, '&nbsp;د عُزياه لوئ لښکر د جنګ دپاره تيار وو. د دې حِساب کِتاب د حننياه د ذمه وارۍ لاندې د هغۀ منشيانو يعى‌ايل او معسياه ساتلو. حننياه د بادشاه د نوکرانو نه يو کس وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10983, '2 Chronicles 26:12', '2 Chronicles', 26, 12, '&nbsp;د لښکر مشرى شپږويشت سوو آفسرانو کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10984, '2 Chronicles 26:13', '2 Chronicles', 26, 13, '&nbsp;د هغوئ لاندې درې لاکه اووۀ زره او پينځۀ سوه داسې تکړه فوجيان وُو چې هغوئ په ښۀ شان د دشمنانو نه د بادشاه حِفاظت کولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10985, '2 Chronicles 26:14', '2 Chronicles', 26, 14, '&nbsp;عُزياه د لښکر دپاره د ډالونو، نېزو، د کلکو ټوپو، زغرو، ليندو، غشو او د ليندو دپاره د کاڼو بندوبست وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10986, '2 Chronicles 26:15', '2 Chronicles', 26, 15, '&nbsp;په يروشلم کښې ماهرو کاريګرانو د غشو د ويشتلو دپاره او د برجونو او د ښار د دېوال د ګوټونو نه د لويو کاڼو غورزولو دپاره څيزونه ايجاد کړل. د هغۀ شُهرت په هر ځائ کښې خور شو او چې د خُدائ پاک نه هغۀ ته کوم مدد مِلاو شوے وو د هغې په وجه هغه ډېر طاقتور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10987, '2 Chronicles 26:16', '2 Chronicles', 26, 16, '&nbsp;خو کله چې عُزياه بادشاه تکړه شو، نو هغه مغروره شو او په دې وجه هغه د تباهۍ طرف ته لاړو. هغۀ د مالِک خُدائ د خپل خُدائ پاک سره خيانت وکړو ځکه چې هغه په خپله د مالِک خُدائ کور ته لاړو او د خوشبويۍ په قربان‌ګاه باندې يې خوشبوئى وسوزوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10988, '2 Chronicles 26:17', '2 Chronicles', 26, 17, '&nbsp;عزرياه اِمام، بادشاه پسې لاړو چې د عزرياه سره اتيا بهادر اِمامان ملګرى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10989, '2 Chronicles 26:18', '2 Chronicles', 26, 18, '&nbsp;دا دې دپاره چې د عُزياه مخه ونيسى. هغوئ ووئيل، ”عُزياه، تۀ دا حق نۀ لرې چې مالِک خُدائ ته خوشبوئى وسوزوى. صِرف د هارون د اولاد اِمامان د دې کار دپاره مخصوص دى. د دې مقدس ځائ نه ووځه ځکه چې تا ګناه کړې ده او مالِک خُدائ به نور ستا عزت نۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10990, '2 Chronicles 26:19', '2 Chronicles', 26, 19, '&nbsp;عُزياه هلته د مالِک خُدائ په کور کښې د خوشبويۍ د قربان‌ګاه سره ولاړ وو او د خوشبويۍ د سوزولو مجمر يې نيولے وو. هغه اِمامانو ته غصه شو او سمدستى د جذام مرض د هغۀ په تندى باندې راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10991, '2 Chronicles 26:20', '2 Chronicles', 26, 20, '&nbsp;عزرياه او نورو اِمامانو د يرې سره د بادشاه تندى ته کتل او بيا يې هغه دې ته مجبور کړو چې د مالِک خُدائ د کور نه لاړ شى. هغه زر زر د هغه ځائ نه لاړو، ځکه چې مالِک خُدائ هغۀ له سزا ورکړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10992, '2 Chronicles 26:21', '2 Chronicles', 26, 21, '&nbsp;عُزياه باقى ټول عُمر د خپل مرض په وجه ناپاک وو. بيا د دې قابل نۀ شو چې د مالِک خُدائ کور ته ورننوتے وو او هغه په يو ځان له کور کښې اوسېدو، خپل ټول کارونه يې پرېښودل. په دې دوران کښې د هغۀ زوئ يوتام په مُلک حکومت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10993, '2 Chronicles 26:22', '2 Chronicles', 26, 22, '&nbsp;د آموص زوئ يشعياه پېغمبر هغه نور ټول څيزونه ليکلى دى چې عُزياه بادشاه د خپلې بادشاهۍ په دوران کښې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10994, '2 Chronicles 26:23', '2 Chronicles', 26, 23, '&nbsp;عُزياه مړ شو او د ښخېدو په شاهى زمکه کښې ښخ شو، خو د جذام د مرض په وجه هغه په شاهى اديره کښې ښخ نۀ شو. د هغۀ زوئ يوتام د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10995, '2 Chronicles 27:1', '2 Chronicles', 27, 1, '&nbsp;يوتام د پينځويشتو کالو په عُمر کښې بادشاه شو او هغۀ شپاړس کاله په يروشلم بادشاهى وکړه. د هغۀ مور يروسا د صدوق لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10996, '2 Chronicles 27:2', '2 Chronicles', 27, 2, '&nbsp;هغۀ د خپل پلار عُزياه په شان هم هغه کار کولو چې په کوم باندې مالِک خُدائ خوشحالېدو، خو د خپل پلار په شان هغۀ داسې ګناه ونۀ کړه لکه چې د هغۀ پلار د مالِک خُدائ کور ته ننوتلے وو. خو خلقو ګناه بيا بيا کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10997, '2 Chronicles 27:3', '2 Chronicles', 27, 3, '&nbsp;هغه يوتام وو چې هغۀ د مالِک خُدائ د کور پاسنۍ دروازه جوړه کړه او د يروشلم په هغه علاقه کښې يې د ښار د دېوال ډېر مرمت هم وکړو چې د هغه علاقې نوم عوفل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10998, '2 Chronicles 27:4', '2 Chronicles', 27, 4, '&nbsp;د يهوداه په غرونو کښې هغۀ ښارونه جوړ کړل او په ځنګلو کښې يې قلعې او برجونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10999, '2 Chronicles 27:5', '2 Chronicles', 27, 5, '&nbsp;هغۀ د عمون بادشاه او د هغۀ د لښکر خِلاف جنګ وکړو او هغوئ له يې شکست ورکړو. بيا هغۀ عمونيان دې ته مجبور کړل چې درې کاله به هر کال دا محصُول ورکوى، درې زره او څلور سوه کلو سپين زر، يو زر ټنه غنم او يو زر ټنه اوربشې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11000, '2 Chronicles 27:6', '2 Chronicles', 27, 6, '&nbsp;د يوتام بادشاهى مضبوطېدله ځکه چې هغۀ په وفادارۍ سره د مالِک خُدائ د خپل خُدائ پاک فرمانبردارى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');